@timkelty Sorry this is a documentation mistake, the helper you are being given in searchFunction only has the  "helper.search()" method on it.

Here's how to use it:

```js
var search = instantsearch({
  searchFunction: function(helper) {
    search.helper.anyHelperMethod();
    search.helper.anyHelperMethod();
    helper.search(); // trigger a new search
  }
})
```
